function check([n, edges], actual) {
  if (!Array.isArray(actual) || actual.length === 0 || !Array.isArray(actual[0])) return false;
  const width = actual[0].length;
  if (width === 0 || actual.some(row => !Array.isArray(row) || row.length !== width) || actual.length * width !== n) return false;
  const used = new Set();
  for (const row of actual) {
    for (const node of row) {
      if (!Number.isInteger(node) || node < 0 || node >= n || used.has(node)) return false;
      used.add(node);
    }
  }
  const pairs = new Set(edges.map(([u, v]) => u * n + v));
  const joined = (a, b) => pairs.has(Math.min(a, b) * n + Math.max(a, b));
  for (let r = 0; r < actual.length; r++) {
    for (let c = 0; c < width; c++) {
      if (c + 1 < width && !joined(actual[r][c], actual[r][c + 1])) return false;
      if (r + 1 < actual.length && !joined(actual[r][c], actual[r + 1][c])) return false;
    }
  }
  // Every neighbouring pair of cells is an edge; the counts match only if every edge is such a pair.
  return actual.length * (width - 1) + width * (actual.length - 1) === edges.length;
}

