function validate([n, edges]) {
  if (n < 2 || n > 50000) return 'n is between 2 and 50000.';
  if (edges.length < 1 || edges.length > 100000) return 'edges holds 1 to 100000 pairs.';
  const graph = Array.from({ length: n }, () => []);
  const pairs = new Set();
  for (const edge of edges) {
    if (edge.length !== 2) return 'Each edge is a pair [u, v].';
    const [u, v] = edge;
    if (!(0 <= u && u < v && v < n)) return 'Each edge [u, v] needs 0 <= u < v < n.';
    if (pairs.has(u * n + v)) return 'The edges must be distinct.';
    pairs.add(u * n + v);
    graph[u].push(v);
    graph[v].push(u);
  }
  // Lay the graph out from a corner, then confirm the layout is a grid with exactly these edges.
  const notGrid = 'These edges cannot be laid out as a grid.';
  let start = 0;
  for (let node = 1; node < n; node++) if (graph[node].length < graph[start].length) start = node;
  const parent = new Array(n).fill(-1);
  parent[start] = start;
  const queue = [start];
  let end = -1;
  for (let head = 0; head < queue.length && end === -1; head++) {
    for (const next of graph[queue[head]]) {
      if (parent[next] !== -1) continue;
      parent[next] = queue[head];
      if (graph[next].length === graph[start].length) { end = next; break; }
      queue.push(next);
    }
  }
  if (end === -1) return notGrid;
  const first = [];
  for (let node = end; node !== start; node = parent[node]) first.push(node);
  first.push(start);
  if (n % first.length !== 0) return notGrid;
  const seen = new Array(n).fill(false);
  for (const node of first) seen[node] = true;
  const rows = [first];
  while (rows.length * first.length < n) {
    const row = [];
    for (const node of rows[rows.length - 1]) {
      const open = graph[node].filter(next => !seen[next]);
      if (open.length !== 1) return notGrid;
      seen[open[0]] = true;
      row.push(open[0]);
    }
    rows.push(row);
  }
  const joined = (a, b) => pairs.has(Math.min(a, b) * n + Math.max(a, b));
  for (let r = 0; r < rows.length; r++) {
    for (let c = 0; c < first.length; c++) {
      if (c + 1 < first.length && !joined(rows[r][c], rows[r][c + 1])) return notGrid;
      if (r + 1 < rows.length && !joined(rows[r][c], rows[r + 1][c])) return notGrid;
    }
  }
  return rows.length * (first.length - 1) + first.length * (rows.length - 1) === edges.length ? null : notGrid;
}

