function constructGridLayout(n, edges) {
  const graph = Array.from({ length: n }, () => []);
  for (const [u, v] of edges) {
    graph[u].push(v);
    graph[v].push(u);
  }
  let start = 0;
  for (let node = 1; node < n; node++) {
    if (graph[node].length < graph[start].length) start = node;
  }
  const cornerDegree = graph[start].length;
  const parent = new Array(n).fill(-1);
  parent[start] = start;
  const queue = [start];
  let end = -1;
  for (let head = 0; end === -1; head++) {
    const node = queue[head];
    for (const neighbor of graph[node]) {
      if (parent[neighbor] !== -1) continue;
      parent[neighbor] = node;
      if (graph[neighbor].length === cornerDegree) {
        end = neighbor;
        break;
      }
      queue.push(neighbor);
    }
  }
  const firstRow = [];
  for (let node = end; node !== start; node = parent[node]) {
    firstRow.push(node);
  }
  firstRow.push(start);
  const seen = new Array(n).fill(false);
  for (const node of firstRow) seen[node] = true;
  const grid = [firstRow];
  while (grid.length * firstRow.length < n) {
    const row = [];
    for (const node of grid[grid.length - 1]) {
      const below = graph[node].find(neighbor => !seen[neighbor]);
      seen[below] = true;
      row.push(below);
    }
    grid.push(row);
  }
  return grid;
}

