function constructGridLayout(n, edges) {
  // Try every rectangle shape and fill its cells in reading order by backtracking.
  const linked = new Set(edges.map(([u, v]) => `${u},${v}`));
  const isEdge = (a, b) => linked.has(a < b ? `${a},${b}` : `${b},${a}`);
  const degree = new Array(n).fill(0);
  for (const [u, v] of edges) {
    degree[u]++;
    degree[v]++;
  }
  for (let rows = 1; rows <= n; rows++) {
    const cols = n / rows;
    if (!Number.isInteger(cols)) continue;
    // A rows x cols grid has exactly this many side-by-side pairs, and each must be an edge.
    if (rows * (cols - 1) + cols * (rows - 1) !== edges.length) continue;
    const cells = [];
    const used = new Array(n).fill(false);
    const fill = (index) => {
      if (index === n) return true;
      const r = Math.floor(index / cols), c = index % cols;
      const sides = (r > 0) + (r < rows - 1) + (c > 0) + (c < cols - 1);
      for (let node = 0; node < n; node++) {
        if (used[node] || degree[node] !== sides) continue;
        if (c > 0 && !isEdge(cells[index - 1], node)) continue;
        if (r > 0 && !isEdge(cells[index - cols], node)) continue;
        used[node] = true;
        cells[index] = node;
        if (fill(index + 1)) return true;
        used[node] = false;
      }
      return false;
    };
    if (fill(0)) return Array.from({ length: rows }, (_, r) => cells.slice(r * cols, (r + 1) * cols));
  }
  return [];
}

