function generate(rand, size) {
  let rows, cols;
  if (size === 'large') {
    // As many cells as fit with at most 2,000 edges, in a range of shapes from a single row to a square.
    rows = [1, 2, 3, 8, 20, 32][Math.floor(rand() * 6)];
    cols = Math.floor((2000 + rows) / (2 * rows - 1));
  } else {
    rows = 1 + Math.floor(rand() * 4);
    cols = (rows === 1 ? 2 : 1) + Math.floor(rand() * 4);
  }
  if (rand() < 0.5) [rows, cols] = [cols, rows];
  const n = rows * cols;
  const label = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [label[i], label[j]] = [label[j], label[i]];
  }
  const edges = [];
  for (let r = 0; r < rows; r++) {
    for (let c = 0; c < cols; c++) {
      const here = label[r * cols + c];
      if (c + 1 < cols) edges.push([Math.min(here, label[r * cols + c + 1]), Math.max(here, label[r * cols + c + 1])]);
      if (r + 1 < rows) edges.push([Math.min(here, label[(r + 1) * cols + c]), Math.max(here, label[(r + 1) * cols + c])]);
    }
  }
  for (let i = edges.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [edges[i], edges[j]] = [edges[j], edges[i]];
  }
  return [n, edges];
}
